AULAS[135] = { ill:'blocos', slides:[
  {type:'capa', title:'Coordenação e subordinação', sub:'Como as orações se relacionam'},
  {type:'objetivos', items:['Diferenciar coordenação e subordinação','Reconhecer a oração principal','Identificar orações independentes e dependentes','Analisar períodos compostos']},
  {type:'pergunta', q:'"Cheguei e jantei." x "Quando cheguei, jantei." Em qual há uma oração que depende da outra?', hint:'Tente ler cada parte sozinha.', ill:'balao'},
  {type:'conceito', title:'Dois processos', text:'Na **coordenação**, as orações são **independentes** sintaticamente. Na **subordinação**, uma oração **depende** de outra (a principal) e exerce uma **função** em relação a ela.', box:'Oração subordinada: funciona como termo da principal (sujeito, objeto, adjunto...).', ill:'blocos'},
  {type:'comparacao', title:'Coordenação x subordinação', left:{h:'Coordenação', items:['Orações independentes','Ligadas por e, mas, ou, portanto','Ex.: Estudei, mas não passei.']}, right:{h:'Subordinação', items:['Uma depende da outra','Ligadas por que, quando, porque, se','Ex.: Não passei porque não estudei.']}},
  {type:'exemplos', title:'Reconhecendo a principal', cards:[['Quero que você venha.','Principal: Quero'],['Quando chover, ficaremos em casa.','Principal: ficaremos em casa'],['O livro que li é ótimo.','Principal: O livro é ótimo'],['Saí porque estava cansado.','Principal: Saí']]},
  {type:'texto', title:'Leitura: o temporal', text:'O céu escureceu e o vento aumentou. Quando os primeiros trovões soaram, as crianças correram para casa. A mãe disse que ninguém sairia até a chuva passar.', source:'Texto criado para esta aula', side:{h:'Classifique', items:['1º período: coordenação ou subordinação?','Qual é a principal do 2º período?','Que oração completa "disse"?']}},
  {type:'passos', title:'Como analisar', steps:[['Conte os verbos','Número de orações'],['Ache os conectivos','e, mas / que, quando'],['Teste a independência','Funciona sozinha?'],['Classifique','Coordenada ou subordinada']]},
  {type:'mapa', title:'Mapa mental', center:'PERÍODO COMPOSTO', nodes:[['Coordenação','Independência'],['Subordinação','Dependência'],['Principal','Rege a subordinada'],['Conectivos coord.','e, mas, ou'],['Conectivos subord.','que, quando, porque'],['Função','Subordinada = termo']]},
  {type:'atividade', title:'Atividade 1: classifique o período', instr:'Coordenação ou subordinação?', items:[{q:'Estudou muito, portanto foi aprovado.', r:'Coordenação'},{q:'Espero que todos compareçam.', r:'Subordinação'},{q:'Ou você estuda, ou você trabalha.', r:'Coordenação'},{q:'Se fizer sol, iremos à praia.', r:'Subordinação'}]},
  {type:'atividade', title:'Atividade 2: oração principal', instr:'Indique a oração principal.', items:[{q:'Embora estivesse cansado, terminou a tarefa.', r:'terminou a tarefa'},{q:'Percebi que a porta estava aberta.', r:'Percebi'}]},
  {type:'quiz', q:'Na subordinação, as orações são...', opts:['independentes','dependentes','sem verbo','sempre negativas'], c:1, why:'A subordinada depende da principal.'},
  {type:'quiz', q:'Qual conectivo costuma introduzir oração subordinada?', opts:['mas','e','quando','ou'], c:2, why:'QUANDO é conjunção subordinativa temporal.'},
  {type:'quiz', q:'"Ele riu e saiu." é exemplo de...', opts:['coordenação','subordinação','oração única','frase nominal'], c:0, why:'Orações independentes ligadas por E.'},
  {type:'gabarito'},
  {type:'resumo', items:['Coordenação une orações independentes.','Subordinação cria dependência.','A subordinada exerce função na principal.','Conectivos ajudam a classificar.']},
  {type:'auto', items:['Diferencio os dois processos.','Encontro a oração principal.','Reconheço conectivos.','Analiso períodos compostos.']},
  {type:'encerramento', casa:'Escreva 3 períodos por coordenação e 3 por subordinação sobre sua rotina.'}
]};

AULAS[136] = { ill:'blocos', slides:[
  {type:'capa', title:'Orações subordinadas', sub:'Conjunções frequentes e usos na escrita'},
  {type:'objetivos', items:['Identificar orações subordinadas introduzidas por conjunções frequentes','Reconhecer relações de causa, tempo, condição, concessão e finalidade','Usar subordinadas para articular ideias','Ampliar a variedade sintática dos textos']},
  {type:'pergunta', q:'Como dizer, numa só frase, que você vai ao parque só se não chover?', hint:'Use uma conjunção de condição.', ill:'balao'},
  {type:'conceito', title:'Subordinadas adverbiais', text:'Muitas subordinadas expressam **circunstâncias** em relação à principal: **causa** (porque), **tempo** (quando), **condição** (se, caso), **concessão** (embora), **finalidade** (para que), **consequência** (tão... que).', box:'A conjunção revela a relação lógica entre as ideias.', ill:'blocos'},
  {type:'exemplos', title:'Conjunções frequentes', cards:[['Causa','porque, como, já que'],['Tempo','quando, enquanto, assim que'],['Condição','se, caso, desde que'],['Concessão','embora, ainda que, mesmo que']]},
  {type:'exemplos', title:'Outras relações', cards:[['Finalidade','para que, a fim de que'],['Consequência','tão... que, tanto... que'],['Comparação','como, mais... do que'],['Conformidade','conforme, segundo, como']]},
  {type:'texto', title:'Leitura: o atleta', text:'Embora fosse o mais jovem da equipe, Davi treinava mais que todos. Acordava cedo para que pudesse correr antes da escola. Como se dedicava tanto, foi convocado para a seleção estadual. Treinou tanto que superou o próprio recorde.', source:'Texto criado para esta aula', side:{h:'Identifique a relação', items:['EMBORA','PARA QUE e COMO','TANTO... QUE']}},
  {type:'passos', title:'Escrevendo com subordinadas', steps:[['Duas ideias','Choveu / o jogo continuou'],['Relação','Concessão'],['Conjunção','embora'],['Período','Embora chovesse, o jogo continuou.']]},
  {type:'mapa', title:'Mapa mental', center:'SUBORDINADAS', nodes:[['Causa','porque'],['Tempo','quando'],['Condição','se'],['Concessão','embora'],['Finalidade','para que'],['Consequência','tão... que']]},
  {type:'atividade', title:'Atividade 1: classifique', instr:'Indique a relação expressa.', items:[{q:'Caso precise, ligue para mim.', r:'Condição'},{q:'Ainda que estivesse cansada, foi à aula.', r:'Concessão'},{q:'Assim que o sinal tocou, todos saíram.', r:'Tempo'},{q:'Falou tão baixo que ninguém ouviu.', r:'Consequência'}]},
  {type:'atividade', title:'Atividade 2: una as orações', instr:'Una usando a relação indicada.', items:[{q:'Faltou energia. A aula foi suspensa. (causa)', r:'Como faltou energia, a aula foi suspensa.'},{q:'Ele é rico. Vive com simplicidade. (concessão)', r:'Embora seja rico, vive com simplicidade.'},{q:'Fale alto. Todos ouvem. (finalidade)', r:'Fale alto para que todos ouçam.'}]},
  {type:'quiz', q:'"Embora" introduz ideia de...', opts:['causa','concessão','tempo','condição'], c:1, why:'Indica oposição que não impede o fato.'},
  {type:'quiz', q:'"Se estudar, passará." SE indica...', opts:['condição','consequência','comparação','finalidade'], c:0, why:'Estabelece uma condição.'},
  {type:'quiz', q:'"Correu tanto que se cansou." Há relação de...', opts:['consequência','concessão','tempo','conformidade'], c:0, why:'O cansaço é resultado.'},
  {type:'gabarito'},
  {type:'resumo', items:['Subordinadas expressam circunstâncias.','Cada conjunção indica uma relação.','Concessão: embora; condição: se.','Variar conectivos enriquece a escrita.']},
  {type:'auto', items:['Reconheço subordinadas.','Identifico relações lógicas.','Uno orações com conjunções.','Vario a sintaxe dos textos.']},
  {type:'encerramento', casa:'Escreva um parágrafo argumentativo usando ao menos 4 conjunções subordinativas diferentes.'}
]};

AULAS[137] = { ill:'quebracabeca', slides:[
  {type:'capa', title:'Conectivos e coesão sequencial', sub:'Encadeando ideias no texto'},
  {type:'objetivos', items:['Compreender a coesão sequencial','Reconhecer conectivos e suas relações','Inferir efeitos de sentido dos articuladores','Usar conectivos em textos argumentativos']},
  {type:'pergunta', q:'O que acontece se tirarmos todos os "porém", "além disso" e "portanto" de um texto?', hint:'Pense na relação entre as ideias.', ill:'balao'},
  {type:'conceito', title:'Coesão sequencial', text:'A **coesão sequencial** garante a **progressão** do texto, encadeando ideias por meio de **conectivos** (conjunções, advérbios, expressões) que indicam relações lógicas.', box:'Conectivos são como placas de trânsito: orientam o leitor.', ill:'quebracabeca'},
  {type:'exemplos', title:'Relações e conectivos', cards:[['Adição','além disso, também, ademais'],['Oposição','porém, no entanto, contudo'],['Conclusão','portanto, logo, assim'],['Explicação/exemplo','ou seja, isto é, por exemplo']]},
  {type:'exemplos', title:'Organizadores textuais', cards:[['Introdução','Em primeiro lugar, Inicialmente'],['Continuidade','Em seguida, Além disso'],['Contraste','Por outro lado'],['Fechamento','Em suma, Por fim']]},
  {type:'texto', title:'Leitura: parágrafo argumentativo', text:'Em primeiro lugar, a prática de esportes melhora a saúde física. Além disso, contribui para o bem-estar emocional, pois libera substâncias associadas ao prazer. No entanto, muitas escolas ainda oferecem poucas aulas de educação física. Portanto, é necessário ampliar esse espaço no currículo.', source:'Texto criado para esta aula', side:{h:'Analise', items:['Que relação indica "Além disso"?','E "No entanto"?','Que conectivo conclui?']}},
  {type:'passos', title:'Revisando a coesão', steps:[['Leia os parágrafos','A sequência é clara?'],['Identifique a relação','Soma, oposição, conclusão?'],['Escolha o conectivo','Adequado à relação'],['Evite repetição','Varie os conectivos']]},
  {type:'mapa', title:'Mapa mental', center:'COESÃO SEQUENCIAL', nodes:[['Adição','além disso'],['Oposição','no entanto'],['Causa','pois'],['Conclusão','portanto'],['Exemplo','por exemplo'],['Organização','em primeiro lugar']]},
  {type:'atividade', title:'Atividade 1: complete', instr:'Complete com um conectivo adequado.', items:[{q:'O projeto é caro; ______, trará muitos benefícios.', r:'Ex.: no entanto'},{q:'Leia o texto; ______, faça o resumo.', r:'Ex.: em seguida'},{q:'Choveu muito; ______, o rio transbordou.', r:'Ex.: por isso / consequentemente'}]},
  {type:'atividade', title:'Atividade 2: corrija o conectivo', instr:'O conectivo está inadequado. Reescreva.', items:[{q:'Ele estudou bastante, portanto não passou.', r:'Ele estudou bastante, mas não passou.'},{q:'O dia estava lindo, porém fomos à praia.', r:'O dia estava lindo, por isso fomos à praia.'}]},
  {type:'quiz', q:'"Ou seja" indica...', opts:['explicação','oposição','tempo','conclusão'], c:0, why:'Reformula ou explica.'},
  {type:'quiz', q:'Qual conectivo expressa oposição?', opts:['além disso','contudo','portanto','por exemplo'], c:1, why:'CONTUDO contrapõe ideias.'},
  {type:'quiz', q:'A coesão sequencial garante...', opts:['a progressão e o encadeamento das ideias','a rima do texto','o tamanho das letras','a pontuação final'], c:0, why:'Liga partes do texto logicamente.'},
  {type:'gabarito'},
  {type:'resumo', items:['Conectivos encadeiam ideias.','Cada conectivo expressa uma relação.','Organizadores estruturam o texto.','Escolha errada compromete o sentido.']},
  {type:'auto', items:['Reconheço conectivos.','Identifico relações lógicas.','Escolho conectivos adequados.','Vario conectivos nos meus textos.']},
  {type:'encerramento', casa:'Escreva um parágrafo sobre tecnologia usando 5 conectivos de relações diferentes.'}
]};

