AULAS[140] = { ill:'microfone', slides:[
  {type:'capa', title:'Debate regrado', sub:'Argumentar, contra-argumentar e respeitar'},
  {type:'objetivos', items:['Compreender o funcionamento do debate regrado','Preparar argumentos e contra-argumentos','Desempenhar papéis no debate','Usar operadores de concordância e discordância']},
  {type:'pergunta', q:'Uniforme escolar deve ser obrigatório? Que argumentos você usaria?', hint:'Pense nos dois lados.', ill:'balao'},
  {type:'conceito', title:'O debate regrado', text:'No **debate regrado**, participantes defendem posições sobre um **tema polêmico** seguindo **regras**: tempo de fala, ordem das intervenções e mediação.', box:'Papéis: mediador, debatedores, plateia e, às vezes, júri.', ill:'microfone'},
  {type:'exemplos', title:'Estratégias argumentativas', cards:[['Dados','Segundo pesquisa do IBGE...'],['Exemplo','Na escola X, a medida funcionou'],['Autoridade','Especialistas afirmam...'],['Contra-argumento','Embora digam que..., na verdade...']]},
  {type:'exemplos', title:'Operadores no debate', cards:[['Concordar','Concordo com o colega, pois...'],['Discordar','Discordo, porque...'],['Concordar em parte','Concordo parcialmente; entretanto...'],['Retomar','Como foi dito anteriormente...']]},
  {type:'texto', title:'Leitura: trecho de debate', text:'MEDIADORA: O grupo A tem 2 minutos.\nGRUPO A: Defendemos o uniforme obrigatório, porque garante segurança e reduz a comparação entre alunos.\nGRUPO B: Concordamos que a segurança é importante; entretanto, o uniforme pode pesar no orçamento das famílias.\nMEDIADORA: Réplica do grupo A, 1 minuto.', source:'Texto criado para esta aula', side:{h:'Analise', items:['Qual é a tese do grupo A?','Que operador o grupo B usa?','Qual é o papel da mediadora?']}},
  {type:'passos', title:'Etapas do debate', steps:[['Abertura','Mediador apresenta o tema'],['Exposição','Cada grupo defende a tese'],['Réplica e tréplica','Contra-argumentos'],['Encerramento','Considerações finais']]},
  {type:'mapa', title:'Mapa mental', center:'DEBATE', nodes:[['Tema polêmico','Duas posições'],['Mediador','Organiza'],['Tese','Posição'],['Argumentos','Sustentação'],['Contra-argumentos','Refutação'],['Respeito','Turnos e escuta']]},
  {type:'atividade', title:'Atividade 1: contra-argumente', instr:'Escreva um contra-argumento.', items:[{q:'"Celular na escola só atrapalha."', r:'Ex.: Pode atrapalhar, mas, com regras, é ferramenta de pesquisa.'},{q:'"Lição de casa é perda de tempo."', r:'Ex.: Embora canse, ela consolida o que foi aprendido.'}]},
  {type:'desafio', title:'Desafio: debate da turma', text:'Realizem um debate regrado sobre um tema escolhido pela turma.', items:['Definam mediador e grupos','Preparem 3 argumentos e 2 contra-argumentos','Respeitem o tempo','Registrem as conclusões em ata'], ill:'megafone'},
  {type:'quiz', q:'No debate regrado, o mediador...', opts:['organiza turnos e tempos','vence o debate','fala o tempo todo','decide sozinho a tese'], c:0, why:'Garante a ordem.'},
  {type:'quiz', q:'"Concordo parcialmente; entretanto..." expressa...', opts:['concordância total','concordância parcial com ressalva','discordância total','neutralidade'], c:1, why:'Aceita parte e contrapõe outra.'},
  {type:'quiz', q:'Contra-argumento é...', opts:['a refutação da posição contrária','um resumo','um aplauso','a apresentação do mediador'], c:0, why:'Responde ao argumento oposto.'},
  {type:'gabarito'},
  {type:'resumo', items:['Debate regrado segue normas.','Argumentos sustentam a tese.','Contra-argumentos respondem à posição oposta.','Operadores marcam concordância e discordância.']},
  {type:'auto', items:['Preparo argumentos.','Contra-argumento com respeito.','Uso operadores de debate.','Respeito turnos e tempos.']},
  {type:'encerramento', casa:'Escolha um tema polêmico e escreva 2 argumentos a favor e 2 contra.'}
]};

