  {type:'exemplos', title:'Estrutura do abaixo-assinado', cards:[['Destinatário','A quem se dirige'],['Texto de justificativa','O problema e o pedido'],['Lista de assinaturas','Nome, documento, assinatura'],['Plataformas online','Petições digitais']]},
  {type:'texto', title:'Leitura: trecho de carta aberta', text:'Carta aberta à Secretaria de Transportes\nNós, estudantes da Escola Estadual Monte Azul, vimos a público solicitar a instalação de uma faixa de pedestres em frente à escola. Diariamente, cerca de 800 alunos atravessam a avenida sem sinalização. Em 2025, foram registrados três atropelamentos no local. Reivindicamos, portanto, a sinalização imediata do trecho.', source:'Carta criada para esta aula', side:{h:'Identifique', items:['Quem assina','O argumento com dados','A reivindicação']}},
  {type:'passos', title:'Produção', steps:[['Problema coletivo','Que afeta muitos'],['Destinatário','Quem resolve'],['Argumentos','Dados e consequências'],['Mobilização','Coletar assinaturas']]},
  {type:'mapa', title:'Mapa mental', center:'PARTICIPAÇÃO', nodes:[['Carta aberta','Pública'],['Abaixo-assinado','Assinaturas'],['Problema','Coletivo'],['Argumentos','Dados'],['Reivindicação','Pedido claro'],['Cidadania','Participação']]},
  {type:'atividade', title:'Atividade 1: análise', instr:'Responda sobre a carta aberta.', items:[{q:'Por que é "aberta"?', r:'Porque é publicada para toda a sociedade, não só para o destinatário'},{q:'Que marcas indicam reivindicação?', r:'"vimos a público solicitar", "Reivindicamos"'},{q:'Que dado fortalece o pedido?', r:'800 alunos e três atropelamentos em 2025'}]},
  {type:'desafio', title:'Desafio: mobilização da turma', text:'Produzam uma carta aberta ou abaixo-assinado sobre um problema real.', items:['Título e destinatário','Dois argumentos com dados','Reivindicação clara','Modelo de lista de assinaturas'], ill:'carta'},
  {type:'quiz', q:'A carta aberta se diferencia da carta comum por...', opts:['ser publicada para a sociedade','ser secreta','não ter destinatário','ser em versos'], c:0, why:'Busca visibilidade pública.'},
  {type:'quiz', q:'O abaixo-assinado tem como principal característica...', opts:['reunir assinaturas de apoio','contar uma história','vender um produto','resumir um livro'], c:0, why:'Mostra apoio coletivo.'},
  {type:'quiz', q:'"Reivindicamos" é um verbo que indica...', opts:['pedido de um direito','dúvida','narração','descrição'], c:0, why:'Marca linguística de reivindicação.'},
  {type:'gabarito'},
  {type:'resumo', items:['Carta aberta é pública e argumentativa.','Abaixo-assinado reúne apoio.','Ambos expõem problema e reivindicação.','São instrumentos de participação cidadã.']},
  {type:'auto', items:['Reconheço os gêneros.','Analiso marcas de reivindicação.','Argumento com dados.','Produzo textos de participação social.']},
  {type:'encerramento', casa:'Pesquise uma petição online real e identifique o problema e o pedido.'}
